# Single-page judge text, with its sentence-level file-source keys retained.
md=(O/'ONE_PAGE_EN.md').read_text();paras=[]
for p in md.strip().split('\n\n'):
    if p.startswith('# '):paras.append('<h1>'+esc(p[2:])+'</h1>');continue
