one='<!doctype html><html lang="en"><meta charset="utf-8"><style>'+css.replace('font-size:14px;line-height:1.85','font-size:12px;line-height:1.62').replace('font-size:24px;line-height:1.45','font-size:25px;line-height:1.25')+'</style><section><div class="brand">MARSFLEX / JUDGE BRIEF</div>'+''.join(paras)+source('Source keys [S1–S14] resolve in docs/SOURCES_EN.md. PIXL: doi.org/10.17189/49zd-2k55. Terrain and results: protected source files and review/final/.')+'<footer>Research scenario. Original code Apache-2.0. External resource terms are separate.</footer></section></html>'
(B/'onepage.html').write_text(one)
print(json.dumps({'history_pages':len(pages),'milestones':len(milestones),'judge_brief_source':str(O/'ONE_PAGE_EN.md')},indent=2))
